<script>export let data;export let form;let amount=0;let members=1;$:share=(Number(amount||0)/members).toFixed(2);</script><div class="narrow"><a href={'/groups/'+data.group.id}>← Back to {data.group.name}</a><div class="card form"><p class="eyebrow">{data.group.name}</p><h1>Add an expense</h1>{#if form?.error}<p class="error" role="alert">{form.error}</p>{/if}<form method="POST"><label>Description<input name="description" placeholder="e.g. Groceries" required/></label><div class="two"><label>Amount (USD)<input name="amount" type="number" min="0.01" step="0.01" bind:value={amount} required/></label><label>Date<input name="date" type="date" value={new Date().toISOString().slice(0,10)} required/></label></div><label>Category<select name="category"><option>Other</option><option>Groceries</option><option>Utilities</option><option>Travel</option><option>Dining</option></select></label><div class="preview"><b>Equal-split preview</b><span>${share} per member</span><small>Splits are stored as whole cents and total exactly.</small></div><button class="button">Save expense</button></form></div></div><style>.narrow{margin:2rem auto;max-width:650px}.form{margin-top:1.5rem}.eyebrow{color:#d26d35;font-weight:800;text-transform:uppercase}.form form{display:grid;gap:1rem;margin-top:1.5rem}.two{display:grid;gap:1rem;grid-template-columns:1fr 1fr}.preview{background:#e6f2ed;border-radius:10px;color:#146c52;display:grid;gap:.3rem;padding:1rem}.preview span{font-size:1.5rem;font-weight:800}.preview small{color:#41645a}@media(max-width:600px){.two{grid-template-columns:1fr}}</style>
